import React from "react";
import ProductCard from "../components/ProductCard";
import "../css/listedenouveaute.css";

export default function listdeNouvaute() {
  return (
    <div className="newitems">
      <ProductCard></ProductCard>
      <ProductCard></ProductCard>
      <ProductCard></ProductCard>
    </div>
  );
}

//first sprint it is gonna be immediately shown in this section, so it's a stack of n elements and that's it, but we can in future sprints give
//the business owner the ability to pin their favorite items to it (in case for example if they think that the sells are not as good as they expected for a certain product)
